head.b:skin:
/* 
-----------------------------------------------
Blogger Template Style
Name:        Codeify MD. Shinha Sarder Edition
Version:     3.0.0
Author:      MD. Shinha Sarder
Author Url:  https://www.mdshinhasarder.com/
----------------------------------------------- */

/*
<!-- Variable definitions -->
<Variable name="keycolor" description="Main Color" type="color" default="#2563eb" value="#2563eb"/>

<Group description="Adjust Widths" selector="body">
  <Variable name="row.x1.width" description="Main Container Width" type="length" default="1080px" min="728px" max="1200px" value="1080px"/>
  <Variable name="row.x2.width" description="Posts Container Width" type="length" default="1080px" min="728px" max="1080px" value="1080px"/>
  <Variable name="row.x3.width" description="Intro Container Width" type="length" default="820px" min="680px" max="820px" value="820px"/>
</Group>

<Group description="Main Theme Colors" selector="body">
  <Variable name="main.color" description="Theme Color" type="color" default="#2563eb" value="#2563eb"/>
  <Variable name="dark.color" description="Dark Color" type="color" default="#0a192f" value="#0a192f"/>
  <Variable name="title.color" description="Title Color" type="color" default="#0f172a" value="#0f172a"/>
  <Variable name="footer.bg" description="Footer Background" type="color" default="#0a192f" value="#0a192f"/>
  <Variable name="footer.color" description="Footer Color" type="color" default="#f8fafc" value="#f8fafc"/>
</Group>

<Group description="Theme Body" selector="body">
  <Variable name="body.background.color" description="Body background color" type="color" default="#f8fafc" value="#f8fafc"/>
  <Variable name="body.background" description="Background" type="background" color="#f8fafc" default="$(color) url() repeat scroll top left" value="$(color) url() repeat scroll top left"/>
  <Variable name="body.text.color" description="Body Text Color" type="color" default="#334155" value="#334155"/>
  <Variable name="body.link.color" description="Body Link Color" type="color" default="$(main.color)" value="#2563eb"/>
</Group>

<Group description="Author Intro" selector=".header-intro">
  <Variable name="intro.bg" description="Background" type="color" default="#081028" value="#081028"/>
  <Variable name="intro.color" description="Color" type="color" default="#ffffff" value="#ffffff"/>
  <Variable name="icon.bg" description="Icon Background" type="color" default="#1e293b" value="#1e293b"/>
  <Variable name="icon.bg.hover" description="Icon Background on Hover" type="color" default="$(main.color)" value="#2563eb"/>
  <Variable name="icon.color" description="Icon Color" type="color" default="#ffffff" value="#ffffff"/>

<!-- Extra Variables -->
<Variable name="body.text.font" description="Font" hideEditor="true" type="font" default="14px 'Karla', sans-serif" value="14px 'Karla', sans-serif"/>
<Variable name="posts.background.color" description="Post background color" hideEditor="true" type="color" default="#fff" value="#ffffff"/>
<Variable name="tabs.font" description="Font 2" hideEditor="true" type="font" default="14px 'Karla', sans-serif" value="14px 'Karla', sans-serif"/>
<Variable name="posts.title.color" description="Post title color" hideEditor="true" type="color" default="$(title.color)" value="#0f172a"/>
<Variable name="posts.text.color" description="Post text color" hideEditor="true" type="color" default="$(body.text.color)" value="#334155"/>
<Variable name="posts.icons.color" description="Post icons color" hideEditor="true" type="color" default="$(main.color)" value="#2563eb"/>
<Variable name="labels.background.color" description="Label background color" hideEditor="true" type="color" default="$(main.color)" value="#2563eb"/>
</Group>
*/

/*-- Google Font --*/
@import url('https://fonts.googleapis.com/css2?family=Karla:ital,wght@0,400;0,600;0,700;1,400&family=Poppins:wght@300;400;500;600;700;800&display=swap');

/*-- Reset CSS --*/
a,abbr,acronym,address,applet,b,big,blockquote,body,caption,center,cite,code,dd,del,dfn,div,dl,dt,em,fieldset,font,form,h1,h2,h3,h4,h5,h6,html,i,iframe,img,ins,kbd,label,legend,li,object,p,pre,q,s,samp,small,span,strike,strong,sub,sup,table,tbody,td,tfoot,th,thead,tr,tt,u,ul,var{padding:0;border:0;outline:0;vertical-align:baseline;background:0 0;text-decoration:none}
form,textarea,input,button{-webkit-appearance:none;-moz-appearance:none;appearance:none;border-radius:0}
dl,ul{list-style-position:inside;font-weight:400;list-style:none}
ul li{list-style:none}
caption,th{text-align:center}
img{border:none;position:relative}
a,a:visited{text-decoration:none}
.clearfix{clear:both}
.section,.widget,.widget ul{margin:0;padding:0}
a{color:$(body.link.color)}
a img{border:0}
abbr{text-decoration:none}
.CSS_LIGHTBOX{z-index:999999!important}
.separator a{clear:none!important;float:none!important;margin-left:0!important;margin-right:0!important}
#navbar-iframe,.widget-item-control,a.quickedit,.home-link,.feed-links{display:none!important}
.center{display:table;margin:0 auto;position:relative}
.widget > h2,.widget > h3{display:none}
.widget iframe,.widget img{max-width:100%}

/*-- Body Content CSS --*/
body{background:$(body.background);background-color:$(body.background.color);font-family:'Poppins','Karla',sans-serif;font-size:14px;font-weight:400;color:$(body.text.color);word-wrap:break-word;margin:0;padding:0}
#outer-wrapper{background-color:#fff;margin:0 auto;box-shadow:0 0 20px rgba(15,23,42,.08)}
.row-x1{width:$(row.x1.width);margin:0 auto}
.row-x2{width:$(row.x2.width);margin:0 auto}
.row-x3{width:$(row.x3.width);margin:0 auto}
#content-wrapper{margin:0 auto;overflow:hidden}
#main-wrapper{float:left;overflow:hidden;width:100%;box-sizing:border-box;word-wrap:break-word;margin:20px 0 0}
.post-image-wrap{position:relative;display:block}
.post-thumb{display:block;position:relative;width:100%;height:100%;object-fit:cover;z-index:1;opacity:0;transition:opacity .17s ease}
.post-thumb.lazy-ify{opacity:1}
.post-title a{color:$(title.color);display:block;transition:color .17s ease}
.post-title a:hover{color:$(main.color)}

/* Header & Navigation */
#header-wrap{position:relative}
.header-header{background-color:#fff;width:100%;height:86px;position:relative;border-bottom:1px solid #e2e8f0}
.header-header.isHomepage{border-bottom:1px solid rgba(0,0,0,0.06)}
.header-header .container{position:relative;margin:0 auto;display:flex;align-items:center;justify-content:space-between;height:86px}
.header-logo{float:left;margin:0 20px 0 0}
.main-logo{position:relative;float:left;width:auto;max-width:280px;max-height:46px;margin:0}
.main-logo .header-image-wrapper{display:flex;align-items:center;gap:10px}
.main-logo img{max-width:44px;max-height:44px;border-radius:50%;object-fit:cover}
.main-logo h1{font-size:22px;line-height:46px;margin:0;font-weight:700}
.main-logo h1 a{color:$(title.color)}
.main-logo #h1-tag{position:absolute;top:-9000px;left:-9000px;display:none;visibility:hidden}
.header-menu{float:left}
#main-menu{position:relative;height:50px;z-index:15}
#main-menu ul#main-menu-nav{display:flex;align-items:center;margin:0;padding:0}
#main-menu ul > li{float:left;position:relative;margin:0;padding:0}
#main-menu ul > li > a{position:relative;height:86px;color:$(title.color);font-size:15px;font-weight:500;line-height:86px;display:inline-block;text-decoration:none;margin:0;padding:0 15px;transition:color .17s}
#main-menu ul > li > a:hover{color:$(main.color)}

.show-search,.hide-search{position:relative;display:flex;align-items:center;justify-content:center;background-color:$(main.color);width:36px;height:36px;line-height:36px;z-index:20;color:#fff;font-size:15px;cursor:pointer;border-radius:100%;transition:background .17s ease}
.show-search:before{content:"\f002";font-family:'Font Awesome 5 Free';font-weight:900}
.hide-search:before{content:"\f00d";font-family:'Font Awesome 5 Free';font-weight:900}
.show-search:hover,.hide-search:hover{background-color:$(dark.color)}
#nav-search{display:none;position:absolute;left:0;top:0;width:100%;height:85px;z-index:99;background-color:#fff;box-sizing:border-box;padding:0 20px}
#nav-search .search-form{width:100%;height:86px;line-height:86px;display:flex;align-items:center;justify-content:space-between}
#nav-search .search-input{width:100%;height:50px;color:$(title.color);font-size:15px;padding:0 15px;border:1px solid #cbd5e1;border-radius:8px}

.header-intro{position:relative;overflow:hidden;background:linear-gradient(135deg, #050b1f 0%, #0a1f44 50%, #050b1f 100%);padding:45px 20px;color:#fff;text-align:center}
.intro-avatar{width:130px;height:130px;display:inline-block;border-radius:50%;padding:4px;background:rgba(255,255,255,0.15);box-shadow:0 10px 25px rgba(0,0,0,0.3);margin-bottom:20px}
.intro-avatar img{width:100%;height:100%;border-radius:50%;object-fit:cover}
.intro-title{font-size:17px;line-height:1.7;max-width:820px;margin:0 auto 20px;color:#cbd5e1;font-weight:400}
ul.intro-social-content{display:flex;justify-content:center;gap:12px;margin:0 auto}
.intro-social-content li a{display:flex;align-items:center;justify-content:center;width:40px;height:40px;background:#1e293b;color:#fff;border-radius:50%;transition:all .2s ease;font-size:16px}
.intro-social-content li a:hover{background:$(main.color);transform:translateY(-2px)}

/* Blog Posts and Typography */
.blog-post{margin-bottom:40px}
.post-title{font-size:24px;font-weight:700;line-height:1.4em;margin-bottom:10px}
.post-body{font-size:15px;line-height:1.8em;color:#334155}
.post-meta{font-size:13px;color:#64748b;margin-bottom:10px}

/* Footer Section */
#footer-wrapper{background-color:$(footer.bg);color:$(footer.color);text-align:center;padding:45px 20px 25px}
.social-footer{display:flex;justify-content:center;gap:14px;margin-bottom:20px}
.social-footer li a{display:flex;align-items:center;justify-content:center;width:38px;height:38px;background:rgba(255,255,255,0.08);color:#fff;border-radius:50%;transition:all .2s ease}
.social-footer li a:hover{background:$(main.color);transform:translateY(-2px)}
.footer-menu{display:flex;justify-content:center;gap:20px;margin-bottom:20px}
.footer-menu li a{color:#94a3b8;font-size:14px;transition:color .2s ease}
.footer-menu li a:hover{color:#fff}
.footer-copyright{font-size:13px;color:#64748b;border-top:1px solid rgba(255,255,255,0.08);padding-top:20px}
.footer-copyright h3{font-size:14px;color:#94a3b8;font-weight:500;margin-bottom:5px}

/* Responsive */
@media screen and (max-width: 880px) {
  .header-menu{display:none}
  .show-mobile-menu{display:block}
}

b:if.b:template-skin:
body#layout{width:920px;position:relative;background-color:#f9f9f9;padding:95px 5px 0;margin:0}
body#layout:before{content:'Theme Options - MD. Shinha Sarder Portfolio Theme';position:absolute;top:0;left:5px;right:5px;height:95px;font-family:Poppins,sans-serif;font-size:20px;color:#0a192f;line-height:95px;text-align:center}
body#layout div.section{background-color:#f1f5f9!important;margin:0 5px 10px!important;padding:16px!important;border:1px solid #e2e8f0}
